from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/test")
async def test_endpoint(value: Optional[str] = Form(default=None)):
    return {"value": value}

client = TestClient(app)

def test_empty_string_as_none():
    # When sending an empty string, it should be interpreted as None if default is None
    response = client.post("/test", data={"value": ""})
    print(f"Response: {response.json()}")
    assert response.json() == {"value": None}

if __name__ == "__main__":
    try:
        test_empty_string_as_none()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
